# -*- coding: utf-8 -*-
"""Brasil / Ciências: 6º ano (BNCC EF06CI01–EF06CI14)"""
from br_sci import H, it, nq, num

D = "A que corresponde esta descrição: {v}?"


def f_micro(R):
    k = R.choice(["aum", "obj", "oc", "tam"])
    oc = R.choice([5, 10, 15, 20])
    ob = R.choice([4, 10, 40, 100])
    if k == "aum":
        return nq("Um microscópio tem ocular de %d× e objetiva de %d×. Qual é o aumento total?" % (oc, ob), oc * ob, [oc + ob, ob, oc * ob * 10, oc * ob // 2], "vezes",
                  "Aumento total = ocular × objetiva = %d × %d = %s vezes." % (oc, ob, num(oc * ob)))
    if k == "obj":
        return nq("O aumento total de um microscópio é %s vezes e a ocular é de %d×. Qual é o aumento da objetiva?" % (num(oc * ob), oc), ob, [oc * ob - oc, oc * ob * oc, oc, ob * 10], "vezes",
                  "%s ÷ %d = %d vezes." % (num(oc * ob), oc, ob))
    if k == "oc":
        return nq("Com objetiva de %d×, o aumento total foi %s vezes. Qual é o aumento da ocular?" % (ob, num(oc * ob)), oc, [oc * ob - ob, oc * ob, ob, oc * 10], "vezes",
                  "%s ÷ %d = %d vezes." % (num(oc * ob), ob, oc))
    t, a = R.choice([(0.01, 400), (0.02, 100), (0.005, 400), (0.1, 40), (0.05, 100), (0.008, 1000)])
    return nq("Uma célula mede %s mm. Vista com aumento de %s vezes, que tamanho ela parece ter?" % (num(t), num(a)), t * a, [t, a, t * a * 10, t * a / 10], "mm",
              "%s mm × %s = %s mm." % (num(t), num(a), num(t * a)))


def f_rot(R):
    k = R.choice(["graus", "horas", "fuso", "sombra"])
    if k == "graus":
        h = R.choice([2, 3, 4, 6, 8, 12])
        return nq("A Terra gira 360° em 24 horas. Quantos graus ela gira em %d horas?" % h, 15 * h, [h * 10, 360 // h, h * 24, 15 * h + 15], "°",
                  "360° ÷ 24 = 15° por hora; 15° × %d = %d°." % (h, 15 * h))
    if k == "horas":
        g = R.choice([30, 45, 60, 90, 120, 180])
        return nq("A Terra gira 15° por hora. Quantas horas leva para girar %d°?" % g, g // 15, [g // 10, g * 15, g // 30 if g >= 60 else 5, g // 15 + 1], "h",
                  "%d° ÷ 15° = %d horas." % (g, g // 15))
    if k == "fuso":
        f = R.choice([1, 2, 3, 4, 5])
        h = R.choice([8, 9, 10, 14, 15])
        return nq("Em Brasília são %d horas. Numa cidade %d fusos a leste é mais tarde. Que horas são lá?" % (h, f), h + f, [h - f, h, h + f * 15, h + 2 * f], "h",
                  "A leste o Sol nasce antes, então é mais tarde: %d + %d = %d horas." % (h, f, h + f))
    a, s = R.choice([(1, 1), (2, 2), (1.5, 1.5), (3, 3), (2, 1), (1, 2)])
    return nq("Uma vara de %s m faz uma sombra de %s m. Um poste ao lado faz sombra de %s m. Qual a altura do poste?" % (num(a), num(s), num(s * 4)), a * 4, [s * 4 + a, a + 4, s * 2, a * s * 4 + 1], "m",
              "A razão altura/sombra é a mesma: %s ÷ %s × %s = %s m." % (num(a), num(s), num(s * 4), num(a * 4)))


